/**
 * APPU voice controller.
 * Speech audio is generated by the n8n workflow and returned with each reply.
 * This client only handles microphone input, playback, subtitles, and sound cues.
 */
class VoiceEngine {
    static isVoiceSupported() {
        const hasRecognition = typeof window !== 'undefined' && Boolean(window.SpeechRecognition || window.webkitSpeechRecognition);
        const hasMediaDevices = typeof navigator !== 'undefined' && Boolean(navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function');
        return Boolean(hasRecognition && hasMediaDevices);
    }

    static get VOICE_MESSAGES() {
        return {
            en: {
                unsupported: "Voice isn't available on this screen — tap 'Type instead' to chat",
                permissionDenied: "Microphone access was denied. Please allow microphone permissions or tap 'Type instead' to chat.",
                noMic: "No microphone found on this device. Tap 'Type instead' to chat.",
                micUnavailableLabel: "Voice unavailable"
            },
            kn: {
                unsupported: "ಈ ಪರದೆಯಲ್ಲಿ ಧ್ವನಿ ಲಭ್ಯವಿಲ್ಲ — ಚಾಟ್ ಮಾಡಲು 'ಬರೆಯಿರಿ' ಟ್ಯಾಪ್ ಮಾಡಿ",
                permissionDenied: "ಮೈಕ್ರೊಫೋನ್ ಅನುಮತಿ ನಿರಾಕರಿಸಲಾಗಿದೆ. ದಯವಿಟ್ಟು ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಅನುಮತಿ ನೀಡಿ ಅಥವಾ 'ಬರೆಯಿರಿ' ಟ್ಯಾಪ್ ಮಾಡಿ.",
                noMic: "ಈ ಸಾಧನದಲ್ಲಿ ಮೈಕ್ರೊಫೋನ್ ಕಂಡುಬಂದಿಲ್ಲ. ಚಾಟ್ ಮಾಡಲು 'ಬರೆಯಿರಿ' ಟ್ಯಾಪ್ ಮಾಡಿ.",
                micUnavailableLabel: "ಧ್ವನಿ ಲಭ್ಯವಿಲ್ಲ"
            },
            hi: {
                unsupported: "इस स्क्रीन पर वॉइस उपलब्ध नहीं है — चैट करने के लिए 'टाइप करें' पर टैप करें",
                permissionDenied: "माइक्रोफ़ोन अनुमति अस्वीकृत है। कृपया ब्राउज़र में अनुमति दें या 'टाइप करें' पर टैप करें.",
                noMic: "इस डिवाइस पर कोई माइक्रोफ़ोन नहीं मिला। 'टाइप करें' पर टैप करें.",
                micUnavailableLabel: "वॉइस अनुपलब्ध"
            }
        };
    }

    getLocalizedVoiceNotice(type) {
        const lang = this.currentLanguage || 'en';
        const dict = VoiceEngine.VOICE_MESSAGES[lang] || VoiceEngine.VOICE_MESSAGES.en;
        if (type === 'unsupported') return dict.unsupported;
        if (type === 'permission-denied') return dict.permissionDenied;
        if (type === 'no-mic') return dict.noMic;
        if (type === 'micUnavailableLabel') return dict.micUnavailableLabel;
        return dict.unsupported;
    }

    constructor(options = {}) {
        this.onSpeechStart = options.onSpeechStart || (() => {});
        this.onSpeechEnd = options.onSpeechEnd || (() => {});
        this.onListeningStart = options.onListeningStart || (() => {});
        this.onListeningEnd = options.onListeningEnd || (() => {});
        this.onTranscript = options.onTranscript || (() => {});
        this.onInterimTranscript = options.onInterimTranscript || (() => {});
        this.onVoiceUnavailable = options.onVoiceUnavailable || (() => {});
        this.onPermissionDenied = options.onPermissionDenied || (() => {});
        this.onSpeechAmplitude = options.onSpeechAmplitude || null;

        this.soundEnabled = true;
        this.autoSpeak = true;
        this.rate = 1;
        this.currentLanguage = 'en';
        this.isListening = false;
        this.isSpeaking = false;
        this.awaitingResponse = false;
        this.liveSessionActive = false;
        this.liveMode = null;            // 'mic' (voice typing, stays on) or 'call' (full-screen call)
        this.currentSpeechText = '';     // what Appu is saying now: used to ignore its own echo
        this.responseWatchdog = null;
        this.silenceTimeoutMs = 60000;
        this.silenceTimer = null;
        this._isReconnecting = false;
        this.subtitleTimer = null;
        this.audioContext = null;
        this.analyserNode = null;
        this.mediaSourceNode = null;
        this._freqDataArray = null;
        this.isVoiceSupported = VoiceEngine.isVoiceSupported();

        this.micButton = document.getElementById('btn-mic');
        this.micLabel = document.querySelector('.mic-label');
        this.subtitleElement = document.getElementById('subtitles-text');
        this.equalizer = document.querySelector('.equalizer');
        this.audioPlayer = new Audio();
        this.audioPlayer.id = 'appu-audio-player';
        this.audioPlayer.hidden = true;
        this.audioPlayer.preload = 'auto';
        this.audioPlayer.volume = 1.0;
        this.audioPlayer.muted = false;
        document.body.appendChild(this.audioPlayer);

        this.initAudioPlayerEvents();
        this.initSpeechRecognition();
    }

    initAudioPlayerEvents() {
        this.audioPlayer.addEventListener('play', () => {
            this.isSpeaking = true;
            this.clearResponseWatchdog();
            this.initAudioAnalyser();
            if (this.recognition && !this.liveSessionActive) {
                try { this.recognition.abort(); } catch {}
            }
            this.updateSpeakingUI(true);
            this.onSpeechStart();
        });
        this.audioPlayer.addEventListener('ended', () => this.handleSpeechFinish());
        this.audioPlayer.addEventListener('error', () => {
            this.streamSubtitles('I could not play that answer. You can still read it here.');
            this.handleSpeechFinish();
        });
    }

    initAudioAnalyser() {
        if (this.analyserNode || !this.audioPlayer) return;
        this.initWebAudio();
        if (!this.audioContext) return;
        try {
            if (!this.mediaSourceNode && typeof this.audioContext.createMediaElementSource === 'function') {
                this.mediaSourceNode = this.audioContext.createMediaElementSource(this.audioPlayer);
                if (typeof this.audioContext.createAnalyser === 'function') {
                    this.analyserNode = this.audioContext.createAnalyser();
                    this.analyserNode.fftSize = 256;
                    this.analyserNode.smoothingTimeConstant = 0.5;
                    this.mediaSourceNode.connect(this.analyserNode);
                    if (this.audioContext.destination) {
                        this.analyserNode.connect(this.audioContext.destination);
                    }
                }
            }
        } catch (err) {
            console.warn('[VoiceEngine] Web Audio Analyser init notice:', err);
        }
    }

    getSpeechAmplitude() {
        if (!this.isSpeaking) return 0;
        if (this.analyserNode && this.audioContext && this.audioContext.state === 'running') {
            try {
                if (!this._freqDataArray) {
                    this._freqDataArray = new Uint8Array(this.analyserNode.frequencyBinCount);
                }
                this.analyserNode.getByteFrequencyData(this._freqDataArray);
                let sum = 0;
                const endBin = Math.min(36, this._freqDataArray.length);
                for (let i = 2; i < endBin; i++) {
                    sum += this._freqDataArray[i];
                }
                const avg = sum / Math.max(1, endBin - 2);
                const norm = Math.min(1, Math.max(0, avg / 120));
                if (typeof this.onSpeechAmplitude === 'function') {
                    this.onSpeechAmplitude(norm);
                }
                return norm;
            } catch (_) {}
        }
        // Natural rhythmic fallback simulation when AnalyserNode is unattached or synthetic
        const t = Date.now() / 1000;
        const wave = Math.sin(t * 14) * 0.35 + Math.sin(t * 22) * 0.25 + 0.35;
        const norm = Math.max(0.12, Math.min(1, wave));
        if (typeof this.onSpeechAmplitude === 'function') {
            this.onSpeechAmplitude(norm);
        }
        return norm;
    }

    handleSpeechFinish() {
        this.clearResponseWatchdog();
        this.awaitingResponse = false;
        this.isSpeaking = false;
        this.updateSpeakingUI(false);
        if (typeof this.onSpeechAmplitude === 'function') {
            this.onSpeechAmplitude(0);
        }
        this.onSpeechEnd();
        if (this.liveSessionActive && !this.isListening) {
            window.setTimeout(() => this.startListening(), 350);
        }
    }

    setPlaybackRate(value) {
        const parsed = Number.parseFloat(value);
        this.rate = Number.isFinite(parsed) ? Math.min(1.35, Math.max(0.75, parsed)) : 1;
        this.audioPlayer.playbackRate = this.rate;
    }

    initWebAudio() {
        if (!this.audioContext) {
            const AudioContext = window.AudioContext || window.webkitAudioContext;
            if (AudioContext) this.audioContext = new AudioContext();
        }
        if (this.audioContext?.state === 'suspended') this.audioContext.resume();
    }

    playTone(frequency, duration = 0.08, volume = 0.04, type = 'sine') {
        if (!this.soundEnabled) return;
        this.initWebAudio();
        if (!this.audioContext) return;
        const oscillator = this.audioContext.createOscillator();
        const gain = this.audioContext.createGain();
        oscillator.type = type;
        oscillator.frequency.value = frequency;
        gain.gain.setValueAtTime(volume, this.audioContext.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, this.audioContext.currentTime + duration);
        oscillator.connect(gain).connect(this.audioContext.destination);
        oscillator.start();
        oscillator.stop(this.audioContext.currentTime + duration);
    }

    playListenStart() {
        this.playTone(520, 0.08);
        window.setTimeout(() => this.playTone(720, 0.1), 70);
    }

    playListenStop() { this.playTone(420, 0.1); }
    playClick() { this.playTone(620, 0.05, 0.025); }
    playMessage() { this.playTone(760, 0.08, 0.03); }

    playSuccess() {
        [520, 660, 820].forEach((tone, index) => {
            window.setTimeout(() => this.playTone(tone, 0.12, 0.035), index * 90);
        });
    }

    toggleSound() {
        this.soundEnabled = !this.soundEnabled;
        if (this.soundEnabled) this.playClick();
        return this.soundEnabled;
    }

    initSpeechRecognition() {
        const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        const hasMediaDevices = typeof navigator !== 'undefined' && Boolean(navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function');
        this.isVoiceSupported = Boolean(Recognition && hasMediaDevices);

        if (!this.isVoiceSupported || !Recognition) {
            this.recognition = null;
            this.applyVoiceUnavailableState();
            return;
        }

        this.recognition = new Recognition();
        this.recognition.continuous = true;
        this.recognition.interimResults = true;
        this.recognition.lang = 'en-IN';

        this.recognition.onstart = () => {
            this.isListening = true;
            this.lastErrorFatal = false;
            this._cycleStart = Date.now();
            this._cycleGotSpeech = false;
            if (!this._isReconnecting) {
                this.updateLiveSessionUI();
                this.playListenStart();
                this.streamSubtitles('Listening — tell me what you want to learn.');
                this.onListeningStart();
            }
            this._isReconnecting = false;
            this.startSilenceTimer();
        };

        try {
            this.recognition.onspeechstart = () => {
                this.resetSilenceTimer();
            };
        } catch (_) {}

        try {
            this.recognition.onaudiostart = () => {
                this.resetSilenceTimer();
            };
        } catch (_) {}

        this.recognition.onresult = event => {
            let finalText = '';
            let interimText = '';
            for (let index = event.resultIndex; index < event.results.length; index += 1) {
                const text = event.results[index][0].transcript;
                if (event.results[index].isFinal) finalText += text;
                else interimText += text;
            }
            // While Appu is talking the mic stays open. Words that Appu itself is saying (its
            // voice coming back through the speaker) are ignored; anything else is the learner
            // interrupting, so Appu stops and listens.
            if (this.isSpeaking) {
                const heard = (finalText || interimText).trim();
                if (!heard || this.isLikelyEcho(heard)) return;
                this.interrupt();
            }
            if (interimText || finalText) {
                this._cycleGotSpeech = true;
                this.resetSilenceTimer();
            }
            if (interimText) this.onInterimTranscript(interimText.trim());
            if (finalText) {
                this.clearSilenceTimer();
                this.awaitingResponse = true;
                this.startResponseWatchdog();
                if (this.recognition) {
                    try { this.recognition.abort(); } catch {}
                }
                this.onTranscript(finalText.trim());
            }
        };

        this.recognition.onerror = event => {
            // 'no-speech' is expected during silent pauses while listening; the 60s silence timer
            // governs session end so we do not abruptly stop or flicker the UI.
            if (event.error === 'no-speech') {
                return;
            }
            // 'aborted' happens when we deliberately stop or abort recognition (e.g. before playback or transcript)
            if (event.error === 'aborted') {
                return;
            }

            const blocked = event.error === 'not-allowed' || event.error === 'service-not-allowed' || event.error === 'audio-capture';
            if (this.liveSessionActive && !blocked) {
                // e.g. 'network': keep the mic on; onend restarts recognition.
                return;
            }
            this.isListening = false;
            this.clearSilenceTimer();
            this.lastErrorFatal = true;
            this.awaitingResponse = false;
            this.updateLiveSessionUI();

            if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
                this.stopLiveSession();
                const notice = this.getLocalizedVoiceNotice('permission-denied');
                this.streamSubtitles(notice);
                this.onPermissionDenied(notice);
                return;
            }
            if (event.error === 'audio-capture') {
                this.stopLiveSession();
                const notice = this.getLocalizedVoiceNotice('no-mic');
                this.streamSubtitles(notice);
                this.onVoiceUnavailable(notice);
                return;
            }
            this.streamSubtitles('I missed that. Tap the microphone and try again.');
        };

        this.recognition.onend = () => {
            // If session was ended intentionally, or awaiting response, or Appu is speaking, or fatal error:
            if (!this.liveSessionActive || this.awaitingResponse || this.lastErrorFatal) {
                this.isListening = false;
                this.clearSilenceTimer();
                this.updateLiveSessionUI();
                this.onListeningEnd();
                return;
            }

            // Browser stopped recognition unexpectedly while still listening (e.g. native stream timeout).
            // Restart gracefully without flickering UI or chiming:
            this._isReconnecting = true;
            try {
                this.recognition.start();
            } catch (err) {
                window.setTimeout(() => {
                    if (this.liveSessionActive && !this.awaitingResponse && !this.lastErrorFatal) {
                        try {
                            this.recognition.start();
                        } catch (_) {}
                    }
                }, 100);
            }
        };
    }

    applyVoiceUnavailableState() {
        if (this.micButton) {
            this.micButton.classList.add('recognition-unavailable', 'voice-unavailable');
            this.micButton.setAttribute('aria-disabled', 'true');
            this.micButton.setAttribute('title', this.getLocalizedVoiceNotice('unsupported'));
        }
        if (this.micLabel) {
            const unavail = this.getLocalizedVoiceNotice('micUnavailableLabel');
            this.micLabel.dataset.idleLabel = unavail;
            this.micLabel.textContent = unavail;
        }
        if (typeof document !== 'undefined') {
            const controlDock = document.querySelector('.control-dock');
            if (controlDock) controlDock.classList.add('voice-unsupported');
            const btnChatMic = document.getElementById('btn-chat-mic');
            if (btnChatMic) {
                btnChatMic.classList.add('voice-unavailable');
                btnChatMic.style.display = 'none';
            }
        }
        this.onVoiceUnavailable(this.getLocalizedVoiceNotice('unsupported'));
    }

    setLanguage(language) {
        if (language === 'kn') {
            this.currentLanguage = 'kn';
            if (this.recognition) this.recognition.lang = 'kn-IN';
        } else if (language === 'hi') {
            this.currentLanguage = 'hi';
            if (this.recognition) this.recognition.lang = 'hi-IN';
        } else {
            this.currentLanguage = 'en';
            if (this.recognition) this.recognition.lang = 'en-IN';
        }
        if (!this.isVoiceSupported) {
            if (this.micLabel) {
                const unavail = this.getLocalizedVoiceNotice('micUnavailableLabel');
                this.micLabel.dataset.idleLabel = unavail;
                this.micLabel.textContent = unavail;
            }
            if (this.micButton) {
                this.micButton.setAttribute('title', this.getLocalizedVoiceNotice('unsupported'));
            }
        }
    }

    toggleLiveSession(mode = 'call') {
        this.initWebAudio();
        if (!this.isVoiceSupported || !this.recognition) {
            const notice = this.getLocalizedVoiceNotice('unsupported');
            this.streamSubtitles(notice);
            this.onVoiceUnavailable(notice);
            return;
        }
        if (this.liveSessionActive && this.liveMode === mode) this.stopLiveSession();
        else this.startLiveSession(mode);
    }

    // Mic button: stays on (voice typing) until tapped again. Each thing the learner says is
    // sent like typed text; talking over Appu interrupts it.
    toggleMic() {
        this.toggleLiveSession('mic');
    }

    // Phone button: the full-screen hands-free call (VoiceCall shows the screen).
    startCall() {
        if (this.liveSessionActive && this.liveMode === 'call') return;
        if (this.liveSessionActive) this.stopLiveSession();
        this.startLiveSession('call');
    }

    startLiveSession(mode = 'call') {
        if (!this.isVoiceSupported || !this.recognition) {
            const notice = this.getLocalizedVoiceNotice('unsupported');
            this.streamSubtitles(notice);
            this.onVoiceUnavailable(notice);
            return;
        }
        this.liveMode = mode === 'mic' ? 'mic' : 'call';
        this.liveSessionActive = true;
        this.lastErrorFatal = false;
        this.awaitingResponse = false;
        this.startListening();
        this.updateLiveSessionUI();
    }

    // If an answer never arrives (network error, no audio), do not leave the mic silently off.
    startResponseWatchdog() {
        this.clearResponseWatchdog();
        if (!this.liveSessionActive) return;
        this.responseWatchdog = window.setTimeout(() => {
            this.responseWatchdog = null;
            if (this.liveSessionActive && this.awaitingResponse && !this.isSpeaking) {
                this.awaitingResponse = false;
                this.startListening();
                this.updateLiveSessionUI();
            }
        }, 45000);
    }

    clearResponseWatchdog() {
        if (this.responseWatchdog) {
            window.clearTimeout(this.responseWatchdog);
            this.responseWatchdog = null;
        }
    }

    // True when the heard words are (mostly) what Appu is saying right now.
    isLikelyEcho(heard) {
        const norm = (value) => String(value || '').toLowerCase().normalize('NFKC')
            .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
        const words = norm(heard).split(' ').filter(Boolean);
        if (words.length === 0) return true;
        const spoken = new Set(norm(this.currentSpeechText).split(' ').filter(Boolean));
        const novel = words.filter((word) => !spoken.has(word));
        return novel.length < Math.max(2, Math.ceil(words.length / 2));
    }

    startSilenceTimer() {
        this.clearSilenceTimer();
        if (!this.liveSessionActive && !this.isListening) return;
        this.silenceTimer = window.setTimeout(() => {
            this.handleSilenceTimeout();
        }, this.silenceTimeoutMs || 60000);
    }

    resetSilenceTimer() {
        this.startSilenceTimer();
    }

    clearSilenceTimer() {
        if (this.silenceTimer) {
            window.clearTimeout(this.silenceTimer);
            this.silenceTimer = null;
        }
    }

    handleSilenceTimeout() {
        this.clearSilenceTimer();
        if (!this.liveSessionActive && !this.isListening) return;
        // The learner decides when listening ends (mic / End call); silence just keeps listening.
        if (this.liveSessionActive) {
            this.startSilenceTimer();
            return;
        }
        this.stopListening();
    }

    stopLiveSession() {
        this.liveSessionActive = false;
        this.liveMode = null;
        this.clearResponseWatchdog();
        this.awaitingResponse = false;
        this._isReconnecting = false;
        this.clearSilenceTimer();
        this.stopListening();
        this.stopSpeaking();
        this.updateLiveSessionUI();
    }

    startListening() {
        if (!this.recognition || this.isListening || this.awaitingResponse) return;
        if (this.isSpeaking && !this.liveSessionActive) return;
        try {
            this.recognition.start();
        } catch (error) {
            if (error.name !== 'InvalidStateError') console.warn('Speech recognition could not start.', error);
        }
    }

    stopListening() {
        this._isReconnecting = false;
        this.clearSilenceTimer();
        if (!this.recognition || !this.isListening) return;
        this.recognition.stop();
        this.playListenStop();
    }

    updateLiveSessionUI() {
        const micOn = this.liveSessionActive && this.liveMode === 'mic';
        if (typeof document !== 'undefined') {
            document.body.classList.toggle('mic-live', micOn);
            const chatMic = document.getElementById('btn-chat-mic');
            if (chatMic) {
                chatMic.classList.toggle('is-live', micOn);
                chatMic.setAttribute('aria-pressed', String(micOn));
            }
        }
        if (!this.micButton) return;
        this.micButton.classList.toggle('active', micOn);
        this.micButton.classList.toggle('is-live', micOn);
        this.micButton.setAttribute('aria-pressed', String(micOn));
        this.micButton.setAttribute('aria-label', micOn ? 'Stop listening' : 'Tap to speak to Appu');
        if (this.micLabel) {
            const idleLabel = this.micLabel.dataset.idleLabel || 'Tap to speak';
            this.micLabel.textContent = micOn ? 'Listening now' : idleLabel;
        }
    }

    updateSpeakingUI(speaking) {
        document.body.classList.toggle('appu-speaking', speaking);
        if (this.equalizer) this.equalizer.classList.toggle('active', speaking);
    }

    async playBackendAudio(audioSource, text = '') {
        const contract = window.AppuVoiceContract;
        const source = contract?.toAudioSource ? contract.toAudioSource(audioSource) : audioSource;
        if (!source || !this.autoSpeak) {
            if (text) this.streamSubtitles(text);
            this.awaitingResponse = false;
            this.onSpeechEnd();
            if (this.liveSessionActive && !this.isListening) {
                window.setTimeout(() => this.startListening(), 350);
            }
            return false;
        }

        this.stopSpeaking();
        if (text) this.streamSubtitles(text);
        this.audioPlayer.src = source;
        this.audioPlayer.playbackRate = this.rate;
        this.audioPlayer.volume = 1.0;
        this.audioPlayer.muted = false;
        try {
            await this.audioPlayer.play();
            return true;
        } catch (error) {
            console.warn('Backend audio playback was blocked.', error);
            if (text && this.speakSynthesis(text)) {
                return true;
            }
            this.streamSubtitles(text || 'Tap the mic again to hear the answer.');
            this.handleSpeechFinish();
            return false;
        }
    }

    /**
     * Staging Streaming Audio Playback using fetch() with Bearer Authentication.
     * Streams chunked MP3 from the server-authorized endpoint.
     */
    async playStream(streamUrl, text = '', accessToken = '') {
        if (!streamUrl || !this.autoSpeak) {
            if (text) this.streamSubtitles(text);
            this.awaitingResponse = false;
            this.onSpeechEnd();
            if (this.liveSessionActive && !this.isListening) {
                window.setTimeout(() => this.startListening(), 350);
            }
            return false;
        }

        // Defensive resolution against configured APPU backend API origin
        let resolvedUrl = null;
        if (typeof AppuBackendClient !== 'undefined' && typeof AppuBackendClient.resolveAudioStreamUrl === 'function') {
            resolvedUrl = AppuBackendClient.resolveAudioStreamUrl(streamUrl);
        } else if (typeof streamUrl === 'string' && streamUrl.trim()) {
            const trimmed = streamUrl.trim();
            const base = (typeof APPU_CONFIG !== 'undefined' && typeof APPU_CONFIG.apiBaseUrl === 'string')
                ? APPU_CONFIG.apiBaseUrl.replace(/\/+$/, '')
                : ((typeof window !== 'undefined' && window.location && /^(localhost|127\.0\.0\.1)(:\d+)?$/i.test(window.location.host)) ? '' : 'https://api.appuai.online');
            if (trimmed.startsWith('/')) {
                resolvedUrl = `${base}${trimmed}`;
            } else {
                try {
                    const parsed = new URL(trimmed);
                    if (parsed.origin === new URL(base).origin) {
                        resolvedUrl = parsed.toString();
                    }
                } catch {}
            }
        }

        if (!resolvedUrl) {
            console.warn('Audio stream URL is invalid or blocked for security:', streamUrl);
            if (text) this.streamSubtitles(text);
            this.onSpeechEnd();
            return false;
        }

        this.stopSpeaking();
        if (text) this.streamSubtitles(text);

        try {
            this.currentStreamController = (typeof AbortController !== 'undefined') ? new AbortController() : null;
            const headers = {};
            if (accessToken && typeof accessToken === 'string' && accessToken.trim()) {
                headers['Authorization'] = `Bearer ${accessToken.trim()}`;
            } else if (typeof AppuBackendClient !== 'undefined' && typeof AppuBackendClient.getStoredGuestToken === 'function') {
                const guestToken = AppuBackendClient.getStoredGuestToken();
                if (guestToken) {
                    headers['X-Guest-Session-Token'] = guestToken;
                }
            }

            const fetchOpts = { method: 'GET', headers };
            if (this.currentStreamController) {
                fetchOpts.signal = this.currentStreamController.signal;
            }

            const response = await fetch(resolvedUrl, fetchOpts);
            if (!response.ok) {
                console.warn('Authenticated audio stream request failed', response.status);
                this.handleSpeechFinish();
                return false;
            }

            if (window.MediaSource && MediaSource.isTypeSupported('audio/mpeg')) {
                const mediaSource = new MediaSource();
                const objectUrl = URL.createObjectURL(mediaSource);
                this.audioPlayer.src = objectUrl;
                this.audioPlayer.playbackRate = this.rate;
                this.audioPlayer.volume = 1.0;
                this.audioPlayer.muted = false;

                const MIN_STARTUP_BUFFER_SECS = 1.2; // Initial buffer cushion to eliminate mid-speech chunk jitter pauses

                mediaSource.addEventListener('sourceopen', async () => {
                    let sourceBuffer;
                    try {
                        sourceBuffer = mediaSource.addSourceBuffer('audio/mpeg');
                    } catch (e) {
                        return;
                    }

                    let isDisposed = false;
                    let hasStartedPlayback = false;
                    let isAppending = false;
                    let streamDone = false;
                    const chunkQueue = [];

                    if (this.currentStreamController) {
                        this.currentStreamController.signal.addEventListener('abort', () => {
                            isDisposed = true;
                            chunkQueue.length = 0;
                            try {
                                if (mediaSource.readyState === 'open' && !sourceBuffer.updating) {
                                    mediaSource.endOfStream();
                                }
                            } catch {}
                        });
                    }

                    const checkAndStartPlayback = () => {
                        if (hasStartedPlayback || isDisposed) return;
                        let bufferedSecs = 0;
                        try {
                            if (sourceBuffer && sourceBuffer.buffered && sourceBuffer.buffered.length > 0) {
                                bufferedSecs = sourceBuffer.buffered.end(sourceBuffer.buffered.length - 1) - sourceBuffer.buffered.start(0);
                            }
                        } catch {}

                        // Start playback once initial threshold is satisfied OR stream has finished downloading
                        if (bufferedSecs >= MIN_STARTUP_BUFFER_SECS || (streamDone && chunkQueue.length === 0)) {
                            hasStartedPlayback = true;
                            this.audioPlayer.play().catch(e => {
                                if (!isDisposed) {
                                    console.warn('Stream play error:', e);
                                    if (text) this.speakSynthesis(text);
                                }
                            });
                        }
                    };

                    const processQueue = () => {
                        if (isDisposed || mediaSource.readyState !== 'open' || !sourceBuffer) return;
                        if (isAppending || sourceBuffer.updating) return;

                        if (chunkQueue.length > 0) {
                            const nextChunk = chunkQueue.shift();
                            try {
                                isAppending = true;
                                sourceBuffer.appendBuffer(nextChunk);
                            } catch (err) {
                                isAppending = false;
                                console.warn('SourceBuffer append error:', err);
                            }
                            return;
                        }

                        checkAndStartPlayback();

                        if (streamDone && !sourceBuffer.updating && mediaSource.readyState === 'open') {
                            try {
                                mediaSource.endOfStream();
                            } catch {}
                        }
                    };

                    sourceBuffer.addEventListener('updateend', () => {
                        isAppending = false;
                        checkAndStartPlayback();
                        processQueue();
                    });

                    sourceBuffer.addEventListener('error', (err) => {
                        isAppending = false;
                        console.warn('SourceBuffer error:', err);
                        processQueue();
                    });

                    const reader = response.body.getReader();

                    try {
                        while (true) {
                            const { done, value } = await reader.read();
                            if (isDisposed) break;

                            if (done) {
                                streamDone = true;
                                processQueue();
                                break;
                            }

                            if (value && value.byteLength > 0) {
                                chunkQueue.push(value);
                                processQueue();
                            }
                        }
                    } catch (readErr) {
                        if (!isDisposed && readErr && readErr.name !== 'AbortError') {
                            console.warn('Audio stream read error:', readErr);
                        }
                    }
                }, { once: true });

                return true;
            } else {
                // Fallback for browsers without MediaSource audio/mpeg support
                const blob = await response.blob();
                const blobUrl = URL.createObjectURL(blob);
                this.audioPlayer.src = blobUrl;
                this.audioPlayer.playbackRate = this.rate;
                this.audioPlayer.volume = 1.0;
                this.audioPlayer.muted = false;
                try {
                    await this.audioPlayer.play();
                    return true;
                } catch (playErr) {
                    console.warn('Audio blob playback prevented:', playErr);
                    if (text && this.speakSynthesis(text)) return true;
                    this.handleSpeechFinish();
                    return false;
                }
            }
        } catch (error) {
            if (error && error.name === 'AbortError') {
                return false;
            }
            console.warn('Audio stream error:', error);
            if (text && this.speakSynthesis(text)) {
                return true;
            }
            this.handleSpeechFinish();
            return false;
        }
    }

    /**
     * Synthesizes speech locally using Web Speech API as resilient zero-latency fallback.
     * Drives subtitles, audio state, and avatar lip sync.
     */
    speakSynthesis(text) {
        // Appu only ever speaks in its own ElevenLabs voice. Without that audio the text is shown
        // as subtitles; the device's built-in voice is never used, on any page or setting.
        if (text) this.streamSubtitles(text);
        this.handleSpeechFinish();
        return false;
    }

    async speak(text, audioSource, audioStreamUrl = null, accessToken = '') {
        this.initWebAudio();
        this.currentSpeechText = text || '';
        if (audioStreamUrl) {
            const played = await this.playStream(audioStreamUrl, text, accessToken);
            if (played) return true;
        }
        if (audioSource) {
            const played = await this.playBackendAudio(audioSource, text);
            if (played) return true;
        }
        // Resilient fallback to local SpeechSynthesis if server audio is absent or failed
        if (text && this.autoSpeak) {
            return this.speakSynthesis(text);
        }
        if (text) this.streamSubtitles(text);
        this.handleSpeechFinish();
        return false;
    }

    stopSpeaking() {
        if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
            try { window.speechSynthesis.cancel(); } catch {}
        }
        if (this.currentStreamController) {
            try { this.currentStreamController.abort(); } catch {}
            this.currentStreamController = null;
        }
        if (this.audioPlayer && !this.audioPlayer.paused) this.audioPlayer.pause();
        if (this.audioPlayer) {
            this.audioPlayer.currentTime = 0;
            this.audioPlayer.volume = 1.0;
            this.audioPlayer.muted = false;
        }
        if (this.isSpeaking) {
            this.isSpeaking = false;
            this.updateSpeakingUI(false);
            if (typeof this.onSpeechAmplitude === 'function') {
                this.onSpeechAmplitude(0);
            }
        }
    }

    // Barge-in: the learner talks (or taps) while Appu is answering. Stop the answer and listen.
    interrupt() {
        if (!this.isSpeaking) return false;
        this.stopSpeaking();
        this.awaitingResponse = false;
        this.onSpeechEnd();
        if (this.liveSessionActive) {
            window.setTimeout(() => this.startListening(), 150);
        }
        return true;
    }

    streamSubtitles(text) {
        if (!this.subtitleElement || !text) return;
        window.clearInterval(this.subtitleTimer);
        const words = String(text).split(/\s+/);
        const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (reducedMotion || words.length < 5) {
            this.subtitleElement.textContent = text;
            if (typeof this.subtitleElement.scrollTop !== 'undefined') {
                this.subtitleElement.scrollTop = this.subtitleElement.scrollHeight || 0;
            }
            return;
        }
        let cursor = 0;
        this.subtitleElement.textContent = '';
        this.subtitleTimer = window.setInterval(() => {
            cursor = Math.min(words.length, cursor + 3);
            this.subtitleElement.textContent = words.slice(0, cursor).join(' ');
            if (typeof this.subtitleElement.scrollTop !== 'undefined') {
                this.subtitleElement.scrollTop = this.subtitleElement.scrollHeight || 0;
            }
            if (cursor >= words.length) window.clearInterval(this.subtitleTimer);
        }, 70);
    }
}

window.VoiceEngine = VoiceEngine;
